using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class BrandKitConfiguration:IEntityTypeConfiguration<BrandKit>{public void Configure(EntityTypeBuilder<BrandKit>b){b.ToTable("brand_kits");b.ConfigureBase();b.HasIndex(x=>x.OrganizationId).IsUnique().HasFilter("[IsDeleted] = 0");foreach(var p in new[]{nameof(BrandKit.PrimaryLogo),nameof(BrandKit.DarkLogo),nameof(BrandKit.LightLogo),nameof(BrandKit.IconLogo),nameof(BrandKit.Favicon)})b.Property(p).HasMaxLength(500);foreach(var p in new[]{nameof(BrandKit.PrimaryColor),nameof(BrandKit.SecondaryColor),nameof(BrandKit.AccentColor),nameof(BrandKit.BackgroundColor),nameof(BrandKit.SurfaceColor),nameof(BrandKit.TextColor),nameof(BrandKit.SuccessColor),nameof(BrandKit.WarningColor),nameof(BrandKit.DangerColor)})b.Property(p).HasMaxLength(7);foreach(var p in new[]{nameof(BrandKit.PrimaryFont),nameof(BrandKit.SecondaryFont),nameof(BrandKit.HeadingFont),nameof(BrandKit.BodyFont)})b.Property(p).HasMaxLength(100);b.Property(x=>x.FontScale).HasPrecision(4,2);b.Property(x=>x.WatermarkSettingsJson).HasColumnType("nvarchar(max)");b.Property(x=>x.QrBrandingJson).HasColumnType("nvarchar(max)");b.Property(x=>x.EmailBrandingJson).HasColumnType("nvarchar(max)");b.HasOne(x=>x.Organization).WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class BrandAssetConfiguration:IEntityTypeConfiguration<BrandAsset>{public void Configure(EntityTypeBuilder<BrandAsset>b){b.ToTable("brand_assets");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Type).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.FileUrl).HasMaxLength(500);b.Property(x=>x.MimeType).HasMaxLength(100);b.Property(x=>x.Tags).HasMaxLength(500);b.HasIndex(x=>new{x.OrganizationId,x.Type,x.CreatedAt});b.HasOne(x=>x.Organization).WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class BrandThemeConfiguration:IEntityTypeConfiguration<BrandTheme>{public void Configure(EntityTypeBuilder<BrandTheme>b){b.ToTable("brand_themes");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(1000);b.Property(x=>x.Kind).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.ConfigurationJson).HasColumnType("nvarchar(max)");b.HasIndex(x=>new{x.OrganizationId,x.Name}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasIndex(x=>new{x.OrganizationId,x.IsActive});b.HasOne(x=>x.Organization).WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.NoAction);}}
